// Configuratie
const NAS_BASE_PATH = '/home/node/n8n-files/projects';

const projectId = $input.first().json.query?.project_id || '';
if (!projectId) throw new Error('Geen project_id opgegeven.');

// We gebruiken het project_id als mapnaam op de NAS
const projectPath = `${NAS_BASE_PATH}/${projectId}`;

return [{ json: { projectId, projectPath } }];

const result = $input.first().json;
const stdout = (result.stdout || '').trim();
const setup = $('Setup').first().json;

try {
  const parsed = JSON.parse(stdout);

  if (!parsed.exists) {
    return [{ json: { success: true, exists: false, project_id: setup.projectId, tree: [] } }];
  }

  // Bouw een boomstructuur: gebouw > verdiep > collector
  const folders = parsed.folders || [];
  const tree = [];
  const gebouwMap = {};
  const verdiepMap = {};

  for (const f of folders) {
    const parts = f.path.split('/');
    if (parts.length === 1) {
      // Gebouw level
      const gebouw = { name: parts[0], path: f.path, verdiepen: [] };
      tree.push(gebouw);
      gebouwMap[parts[0]] = gebouw;
    } else if (parts.length === 2) {
      // Verdiep level
      const parent = gebouwMap[parts[0]];
      if (parent) {
        const verdiep = { name: parts[1], path: f.path, collectoren: [] };
        parent.verdiepen.push(verdiep);
        verdiepMap[f.path] = verdiep;
      }
    } else if (parts.length === 3) {
      // Collector level
      const parentPath = parts[0] + '/' + parts[1];
      const parent = verdiepMap[parentPath];
      if (parent) {
        parent.collectoren.push({ name: parts[2], path: f.path });
      }
    }
  }

  return [{ json: { success: true, exists: true, project_id: setup.projectId, tree } }];
} catch (e) {
  return [{ json: { success: false, error: 'Kan mappen niet lezen: ' + e.message, project_id: setup.projectId } }];
}
